    "e": "เฉลยข้อ ข.\n\nวิธีทำ: อ่านภาพที่กำหนดให้ทีละตำแหน่ง (ตัวอักษร เครื่องหมาย หรือรายละเอียดย่อย) แล้วเทียบกับตัวเลือกทั้งสี่ ตัวเลือกที่ตรงกับภาพต้นฉบับทุกตำแหน่งเท่านั้นจึงถูก ข้อผิดพลาดที่พบบ่อยคือความยาวของภาพไม่เท่ากัน สลับตำแหน่ง หรือเปลี่ยนตัวอักษรหนึ่งตัว ให้ไล่ทีละตัวจากซ้ายไปขวาและตัดตัวเลือกที่ไม่ตรงออก\nข้อนี้เป็นข้อภาพล้วน ต้นฉบับไม่ได้พิมพ์คำอธิบายไว้ ข้อความข้างต้นจึงเป็นหลักการคิดทั่วไป ไม่ได้ยืนยันตัวเลือกใดโดยเฉพาะ\n(คำอธิบายเพิ่มเติมจากปัญญาประดิษฐ์)",
